def _pair_count_spec(xs, t):
    n = len(xs)
    return sum(1 for i in range(n) for j in range(i + 1, n) if xs[i] + xs[j] == t)


def count_pairs_sum(xs: list[int], t: int) -> int:
    """Count pairs of positions i < j with xs[i] + xs[j] == t.

    pre: len(set(xs)) == len(xs)
    post: __return__ == _pair_count_spec(xs, t)
    """
    counts = {}
    total = 0
    for x in xs:
        total += counts.get(t - x, 0)
        counts[x] = counts.get(x, 0) + 1
    return total

