def _has_unique_mode(xs: list[int]) -> bool:
    """Return True if the empty list, or a list where exactly one value has the maximum count."""
    if not xs:
        return True
    counts = {}
    for v in xs:
        counts[v] = counts.get(v, 0) + 1
    top = max(counts.values())
    return sum(1 for c in counts.values() if c == top) == 1


def most_frequent(xs: list[int]) -> int | None:
    """Return the value that appears most often in xs, or None for the empty list.

    pre: _has_unique_mode(xs)
    post: (__return__ is None) == (len(xs) == 0)
    post: __return__ is None or __return__ in xs
    post: __return__ is None or all(xs.count(v) < xs.count(__return__) for v in set(xs) if v != __return__)
    """
    counts = {}
    for v in xs:
        counts[v] = counts.get(v, 0) + 1
    best = None
    best_count = 0
    for v, c in counts.items():
        if c > best_count:
            best = v
            best_count = c
    return best

